import sympy as sp
from mathverify.verifier import verify
from mathverify.sandbox.exactsets import exact_solveset

X = {"name": "x", "domain": "real"}


def run(kind, params, payload, akind, shape, givens=(), vars_=(X,)):
    ir = {"task": {"kind": kind, "params": params}, "vars": list(vars_), "givens": list(givens), "answer_shape": shape}
    sol = {"claimed_answer": {"kind": akind, "payload": payload}, "steps": []}
    return verify(ir, sol).verdict


if __name__ == "__main__":
    x = sp.Symbol("x", real=True)
    print(exact_solveset(sp.Eq(sp.Abs(x), sp.sqrt(2*x + 1)), x, sp.S.Reals))          # new {1+sqrt(2)}
    print(exact_solveset(sp.Abs(x - 2)*sp.log(x - 1) < 0, x, sp.S.Reals))               # new EmptySet
    print(exact_solveset(sp.Eq((sp.Abs(x - 3) - sp.Rational(1, 2))*sp.log(x - 2), 0), x, sp.S.Reals))  # new {3, 7/2}
    cr = {"expr": "Abs(x) - sqrt(2*x + 1)", "var": "x"}
    print(run("count_roots", cr, "2", "count", "count"))   # new INCORRECT (base CORRECT)
    print(run("count_roots", cr, "1", "count", "count"))   # new CORRECT  (base INCORRECT)
    cr2 = {"expr": "(Abs(x - 3) - 1/2)*log(x - 2)", "var": "x"}
    print(run("count_roots", cr2, "3", "count", "count"))  # new INCORRECT (base CORRECT)
    print(run("solve_inequality", {"inequality": "Abs(x - 2)*log(x - 1) < 0", "var": "x"}, "Interval.open(1, 2)", "interval", "set"))  # new UNKNOWN, base CORRECT
    print(run("evaluate", {"expr": "x"}, "1 - sqrt(2)", "value", "scalar", ["Abs(x) = sqrt(2*x + 1)", "x < 0"]))  # new UNKNOWN, base CORRECT
    print(run("evaluate", {"expr": "x"}, "1 - sqrt(2)", "value", "scalar", ["Abs(x) = sqrt(2*x + 1)"]))  # new INCORRECT, base UNKNOWN (target_not_unique)
    XI = {"name": "x", "domain": "integer"}
    g = ["(Abs(x) + Abs(x - 10) - 10)*log(x - 6) = 0"]
    print(run("count_integers", {"var": "x"}, "4", "count", "count", g, (XI,)))  # new INCORRECT, base CORRECT
    print(run("count_integers", {"var": "x"}, "1", "count", "count", g, (XI,)))  # new CORRECT, base INCORRECT
    print(run("solve_equation", {"equation": g[0], "var": "x"}, "{10}", "set", "set"))  # new CORRECT (!), base UNKNOWN
