from mathverify.verifier import verify

X = {"name": "x", "domain": "real"}


def eq(e, givens, payload):
    ir = {"task": {"kind": "solve_equation", "params": {"equation": e, "var": "x"}}, "vars": [X], "givens": list(givens), "answer_shape": "set"}
    sol = {"claimed_answer": {"kind": "set", "payload": payload}, "steps": []}
    r = verify(ir, sol)
    alg = next(la for la in r.layers if la.layer == "certify.algebra")
    return r.verdict, (alg.evidence or {}).get("reason")


if __name__ == "__main__":
    print(eq("Abs(x - 3) = 3 - x", ["x >= 3"], "{3}"))
    print(eq("Abs(x) = x", ["x <= 0"], "{0}"))
    print(eq("Abs(x) = -x", ["x >= 0"], "{0}"))
    print(eq("Max(x, 2) = 2", ["x >= 2"], "{2}"))
    print(eq("Abs(x - 1) + Abs(x + 1) = 2", ["x >= 1"], "{1}"))
