import sympy as sp
from mathverify.verifier import verify
from mathverify.sandbox.exactsets import exact_solveset

X = {"name": "x", "domain": "real"}


def croots(e, payload):
    ir = {"task": {"kind": "count_roots", "params": {"expr": e, "var": "x"}}, "vars": [X], "givens": [], "answer_shape": "count"}
    return verify(ir, {"claimed_answer": {"kind": "count", "payload": payload}, "steps": []}).verdict


if __name__ == "__main__":
    x = sp.Symbol("x", real=True)
    print(exact_solveset(sp.Eq(x / sp.sign(x), 2), x, sp.S.Reals))                       # new ConditionSet, base {-2, 2}
    print(exact_solveset(sp.Eq(1 / (x - sp.Abs(x)), -sp.Rational(1, 2)), x, sp.S.Reals))  # new ConditionSet, base {-1}
    print(croots("x/sign(x) - 2", "2"))          # new UNKNOWN, base CORRECT
    print(croots("1/(x - Abs(x)) + 1/2", "1"))   # new UNKNOWN, base CORRECT

